/// The active context: the OpenTelemetry current context, or — when it has no span — the
/// context of the current `tracing` span (via `tracing-opentelemetry`).
pub fn active_context() -> Context {
    let cx = Context::current();
    if cx.span().span_context().is_valid() {
        return cx;
    }
    let from_tracing = ::tracing::Span::current().context();
    if from_tracing.span().span_context().is_valid() {
        from_tracing
    } else {
        cx
    }
}

/// Starts a span and returns the context that holds it.
pub fn start_span(name: impl Into<Cow<'static, str>>, opts: SpanOptions) -> Context {
    let parent = opts.parent.unwrap_or_else(active_context);
    let builder = SpanBuilder::from_name(name.into())
        .with_kind(opts.kind.unwrap_or(SpanKind::Internal))
        .with_attributes(opts.attributes)
        .with_links(opts.links);
    match opts.tracer {
        Some(tracer) => {
            let span = tracer.build_with_context(builder, &parent);
            parent.with_span(span)
        }
        None => {
            let scope = opentelemetry::InstrumentationScope::builder(SCOPE)
                .with_version(env!("CARGO_PKG_VERSION"))
                .build();
            let tracer = opentelemetry::global::tracer_with_scope(scope);
            let span = tracer.build_with_context(builder, &parent);
            parent.with_span(span)
        }
    }
}

fn panic_message(payload: &(dyn Any + Send)) -> String {
    if let Some(s) = payload.downcast_ref::<&str>() {
        format!("panic: {s}")
    } else if let Some(s) = payload.downcast_ref::<String>() {
        format!("panic: {s}")
    } else {
        "panic".to_string()
    }
}

pub(crate) fn mark_error_on<E: fmt::Display + ?Sized>(
    span: &SpanRef<'_>,
    type_name: &str,
    err: &E,
) {
    let message = err.to_string();
    span.add_event(
        "exception",
        vec![
            KeyValue::new("exception.type", type_name.to_string()),
            KeyValue::new("exception.message", message.clone()),
        ],
    );
    span.set_status(Status::error(message));
}

fn finish<T, E: fmt::Display>(
    cx: &Context,
    outcome: std::thread::Result<std::result::Result<T, E>>,
) -> std::result::Result<T, E> {
    let span = cx.span();
    match &outcome {
        Ok(Ok(_)) => {}
        Ok(Err(e)) => mark_error_on(&span, std::any::type_name::<E>(), e),
        Err(payload) => mark_error_on(&span, "panic", &panic_message(payload.as_ref())),
    }
    span.end();
    match outcome {
        Ok(result) => result,
        Err(payload) => resume_unwind(payload),
    }
}

