/// ```no_run
/// # use grow_zipkin::tracing::{with_span, SpanOptions};
/// # async fn demo() -> Result<(), std::io::Error> {
/// let n = with_span("load-user", SpanOptions::default(), async { Ok::<_, std::io::Error>(42) }).await?;
/// # Ok(()) }
