pub async fn with_span<T, E, Fut>(
    name: impl Into<Cow<'static, str>>,
    opts: SpanOptions,
    fut: Fut,
) -> std::result::Result<T, E>
where
    Fut: Future<Output = std::result::Result<T, E>>,
    E: fmt::Display,
{
    let cx = start_span(name, opts);
    let outcome = AssertUnwindSafe(fut.with_context(cx.clone()))
        .catch_unwind()
        .await;
    finish(&cx, outcome)
}

